<script>
const modal=document.getElementById('transaction-modal'),form=document.getElementById('transaction-form'),deleteModal=document.getElementById('delete-modal');
const baseUrl=@json(route('transactions.store')),today=@json(now()->format('Y-m-d'));
let hasReceipt=false;
const rupiah=new Intl.NumberFormat('id-ID',{maximumFractionDigits:0});
function moneyValue(value){return Number(String(value).replace(/[^0-9]/g,''))||0;}
function syncMoney(){
    for(const field of form.querySelectorAll('[data-money]')){
        const digits=field.value.replace(/[^0-9]/g,'').replace(/^0+(?=\d)/,'');
        const caret=field.selectionStart;
        const digitsBefore=field.value.slice(0,caret).replace(/[^0-9]/g,'').length;
        field.value=digits?rupiah.format(Number(digits)):'';
        if(document.activeElement===field){let position=0,count=0;while(position<field.value.length&&count<digitsBefore){if(/[0-9]/.test(field.value[position]))count++;position++;}field.setSelectionRange(position,position);}
    }
    const amount=moneyValue(form.elements.amount.value),discount=moneyValue(form.elements.discount.value);
    form.elements.amount.setCustomValidity(amount>0&&amount<=9999999999999?'':'Masukkan nominal antara Rp 1 dan Rp 9.999.999.999.999.');
    form.elements.discount.setCustomValidity(discount<=amount?'':'Diskon tidak boleh melebihi nominal.');
    document.getElementById('transaction-total').textContent='Rp '+rupiah.format(Math.max(0,amount-discount));
}
form.querySelectorAll('[data-money]').forEach(field=>field.addEventListener('input',syncMoney));
function syncReceipt(){const required=form.elements.type.value==='pengeluaran'&&!hasReceipt;form.elements.attachment.required=required;document.getElementById('receipt-hint').textContent=hasReceipt?'Kosongkan untuk tetap menggunakan bukti lama. JPG, PNG, PDF; maks. 5 MB.':(required?'Wajib untuk pengeluaran. ':'')+'JPG, PNG, PDF; maks. 5 MB.';}
function openEditor(data=null){form.reset();document.getElementById('modal-errors').hidden=true;const editing=!!data;form.action=editing?baseUrl+'/'+data.id:baseUrl;form.elements._method.value=editing?'PUT':'POST';form.elements._form.value=editing?'edit':'create';form.elements._transaction_id.value=data?.id||'';document.getElementById('modal-title').textContent=editing?'Edit transaksi':'Catat transaksi';document.getElementById('save-transaction').textContent=editing?'Simpan perubahan':'Simpan transaksi';form.elements.date.value=today;hasReceipt=!!data?.attachment;const receipt=document.getElementById('existing-receipt');receipt.hidden=!hasReceipt;if(hasReceipt)receipt.href=baseUrl+'/'+data.id+'/lampiran';else receipt.removeAttribute('href');if(data)for(const key of ['type','date','category','description'])form.elements[key].value=data[key];if(data){form.elements.amount.value=rupiah.format(Number(data.amount)+Number(data.discount||0));form.elements.discount.value=rupiah.format(Number(data.discount||0));}syncMoney();syncReceipt();modal.showModal();document.body.classList.add('modal-open');}
document.querySelectorAll('[data-create]').forEach(button=>button.addEventListener('click',()=>openEditor()));
document.querySelectorAll('[data-edit]').forEach(button=>button.addEventListener('click',()=>openEditor(JSON.parse(button.dataset.edit))));
document.querySelectorAll('[data-delete]').forEach(button=>button.addEventListener('click',()=>{document.getElementById('delete-form').action=baseUrl+'/'+button.dataset.delete;document.getElementById('delete-description').textContent=button.dataset.description;deleteModal.showModal();document.body.classList.add('modal-open');}));
document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
for(const dialog of [modal,deleteModal]){dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));}
form.elements.type.addEventListener('change',syncReceipt);
document.querySelectorAll('dialog form').forEach(item=>item.addEventListener('submit',()=>{item.querySelector('button[type="submit"],button:not([type])').disabled=true;}));
@if($formErrors->any() && in_array(($previousInput['_form'] ?? null),['create','edit']))
const previous=@json($previousInput);const previousRows=@json($transactions->getCollection()->keyBy('id'));const original=previous._form==='edit'?previousRows[previous._transaction_id]:null;openEditor(original||null);if(previous._form==='edit'){form.action=baseUrl+'/'+previous._transaction_id;form.elements._method.value='PUT';form.elements._form.value='edit';form.elements._transaction_id.value=previous._transaction_id;document.getElementById('modal-title').textContent='Edit transaksi';}for(const key of ['type','date','category','amount','discount','description'])if(previous[key]!==undefined)form.elements[key].value=previous[key];syncMoney();syncReceipt();document.getElementById('modal-errors').hidden=false;
@elseif(request()->getQueryString() === null)
if(location.hash==='#catat')openEditor();
@endif
</script>
